export const searchSettingsLocales = Object.fromEntries(Object.entries(copy).map(([locale, values]) => [locale, Object.fromEntries(keys.map((key, index) => [key, values[index]]))]))
export function searchSettingsText(locale, key) {
  return (searchSettingsLocales[String(locale || '').toLowerCase().split('-')[0]] || searchSettingsLocales.en)[key] || searchSettingsLocales.en[key] || key
}
